# Old free-form categories -> new fixed item types.
CATEGORY_TO_ITEM_TYPE = {
    "weapons": "weapon",
    "shields": "shield",
    "grenade-mods": "grenade_mod",
    "grenades": "grenade_mod",
    "relics": "relic",
    "class-mods": "class_mod",
}


def categories_to_item_types(apps, schema_editor):
    Item = apps.get_model("arcaniawiki", "Item")
    for item in Item.objects.select_related("category"):
        item.item_type = CATEGORY_TO_ITEM_TYPE.get(item.category.slug, "weapon")
        item.save(update_fields=["item_type"])


